export const DICTATION_STREAM_ERROR_CODES = [
  "unauthenticated",
  "forbidden",
  "auth_mismatch",
  "too_many_connections",
  "rate_limited",
  "invalid_message",
  "already_active",
  "not_active",
  "buffer_overflow",
  "max_duration",
  "provider_error",
  "provider_unavailable",
  "internal",
];
export const DICTATION_STREAM_CLOSE_CODES = {
  normal: 1000,
  goingAway: 1001,
  policyViolation: 1008,
  messageTooBig: 1009,
  idleTimeout: 4000,
  unauthenticated: 4001,
  maxLifetime: 4002,
  forbidden: 4003,
  tooManyConnections: 4008,
  rateLimited: 4029,
};
export function parseDictationStreamServerMessage(data) {
  const value = parseJsonObject(data);
  if (!value) return undefined;
  switch (value["type"]) {
    case "ready":
      return parseReady(value);
    case "result":
      return parseResult(value);
    case "error":
      return parseError(value);
    case "pong":
      return { type: "pong" };
    default:
      return undefined;
  }
}
function parseJsonObject(data) {
  if (typeof data !== "string") return undefined;
  try {
    const value = JSON.parse(data);
    if (!isJsonObject(value)) return undefined;
    return value;
  } catch {
    return undefined;
  }
}
function parseReady(value) {
  const { dictationId } = value;
  if (typeof dictationId !== "string") return undefined;
  return { type: "ready", dictationId };
}
function parseResult(value) {
  const { dictationId, rawText, cleanedText } = value;
  const timings = parseTimings(value["timings"]);
  if (typeof dictationId !== "string" || typeof rawText !== "string")
    return undefined;
  if (typeof cleanedText !== "string" || !timings) return undefined;
  return { type: "result", dictationId, rawText, cleanedText, timings };
}
function parseTimings(value) {
  if (!isJsonObject(value)) return undefined;
  const { finalizeMs, formatMs, totalMs } = value;
  if (typeof finalizeMs !== "number" || typeof formatMs !== "number")
    return undefined;
  if (typeof totalMs !== "number") return undefined;
  return { finalizeMs, formatMs, totalMs };
}
function parseError(value) {
  const { code, message, dictationId } = value;
  return {
    type: "error",
    // An unknown code (a newer server) still fails the dictation, as a generic server error.
    code: isErrorCode(code) ? code : "internal",
    message: typeof message === "string" ? message : "Dictation stream error",
    ...(typeof dictationId === "string" ? { dictationId } : {}),
  };
}
function isErrorCode(value) {
  return DICTATION_STREAM_ERROR_CODES.some((code) => code === value);
}
function isJsonObject(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
